def resolve(path, cwd, links):
    def split_parts(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    link_count = 0

    if path.startswith('/'):
        current = []
        queue = split_parts(path)
    else:
        current = split_parts(cwd)
        queue = split_parts(path)

    while queue:
        comp = queue.pop(0)
        if comp == '..':
            if current:
                current.pop()
        else:
            current.append(comp)
            candidate = '/' + '/'.join(current)
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                if target.startswith('/'):
                    current = []
                    new_parts = split_parts(target)
                else:
                    current.pop()  # remove the link name, leaving its directory
                    new_parts = split_parts(target)
                queue = new_parts + queue

    return '/' + '/'.join(current)

